-- ============================================================================
-- Migration: 00007_expand_45_services_seed.sql
-- Description: Expand seed dataset with 45 bus services across 15 popular Indian route pairs
-- ============================================================================

-- 1. SEED ADDITIONAL OPERATORS
ON CONFLICT (id) DO NOTHING;

-- 2. SEED BUSES (45 Buses: b0000000-0000-0000-0000-000000000001 to ...0045)
ON CONFLICT (id) DO UPDATE SET
    bus_type = EXCLUDED.bus_type,
    operator_id = EXCLUDED.operator_id;

-- 3. SEED PHYSICAL BUS_SEATS TEMPLATES FOR ALL BUSES
DO $$
DECLARE
    bus_rec RECORD;
BEGIN
    FOR bus_rec IN SELECT id FROM buses LOOP
        -- Lower Deck Seater Seats (Rows 1 to 10)
            -- Upper Deck Sleeper Berths (Rows 1 to 3)
            (bus_rec.id, 'U1', 'upper', 1, 1, 'sleeper'), (bus_rec.id, 'U2', 'upper', 1, 2, 'sleeper'), (bus_rec.id, 'U3', 'upper', 1, 4, 'sleeper'), (bus_rec.id, 'U4', 'upper', 1, 5, 'sleeper'),
            (bus_rec.id, 'U5', 'upper', 2, 1, 'sleeper'), (bus_rec.id, 'U6', 'upper', 2, 2, 'sleeper'), (bus_rec.id, 'U7', 'upper', 2, 4, 'sleeper'), (bus_rec.id, 'U8', 'upper', 2, 5, 'sleeper'),
            (bus_rec.id, 'U9', 'upper', 3, 1, 'sleeper'), (bus_rec.id, 'U10', 'upper', 3, 2, 'sleeper'), (bus_rec.id, 'U11', 'upper', 3, 4, 'sleeper'), (bus_rec.id, 'U12', 'upper', 3, 5, 'sleeper')
        ON CONFLICT (bus_id, seat_label) DO NOTHING;
    END LOOP;
END $$;

-- 4. SEED 45 SCHEDULES Across 15 Route Pairs
ON CONFLICT (id) DO UPDATE SET
    origin = EXCLUDED.origin,
    destination = EXCLUDED.destination,
    departure_time = EXCLUDED.departure_time,
    arrival_time = EXCLUDED.arrival_time,
    price = EXCLUDED.price,
    total_seats = EXCLUDED.total_seats,
    badge = EXCLUDED.badge;

-- 5. SEED BOARDING POINTS
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, address = EXCLUDED.address, time = EXCLUDED.time;

-- 6. SEED DROPPING POINTS
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, address = EXCLUDED.address, time = EXCLUDED.time;

-- 7. SEED SCHEDULE_SEATS FOR ALL 45 SCHEDULES
DO $$
DECLARE
    sched_rec RECORD;
BEGIN
    FOR sched_rec IN SELECT id, bus_id, price FROM schedules LOOP
        SELECT 
            sched_rec.id AS schedule_id,
            bs.id AS bus_seat_id,
            CASE WHEN bs.seat_type = 'sleeper' THEN sched_rec.price + 300 ELSE sched_rec.price END AS price,
            CASE 
                WHEN bs.seat_label IN ('1B', '2C', 'U2', 'U7') THEN 'occupied'
                WHEN bs.seat_label IN ('3A', '3B') THEN 'reserved'
                ELSE 'available'
            END AS status
        FROM bus_seats bs
        WHERE bs.bus_id = sched_rec.bus_id
        ON CONFLICT (schedule_id, bus_seat_id) DO NOTHING;
    END LOOP;
END $$;
